using System.Text.Json;
using EscalaLivre.Application.Contracts;
using EscalaLivre.Domain.Scheduling;
using EscalaLivre.Infrastructure.ImportExport;
namespace EscalaLivre.Adapter.Tests;
public sealed class EmploymentGenerationTests {
 [Theory][InlineData(false)][InlineData(true)]public void GenerationUsesDatedRoleAndSkipsInactive(bool inactive){using var j=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"employment-scenarios.json")));var r=j.RootElement.GetProperty("scenarios")[1].GetProperty("request").Deserialize<ScheduleRequest>(ScheduleJson.CreateOptions())!;var e=r.Document.Employees[0] with{InactiveFrom=inactive?new DateOnly(2026,11,15):null};var d=r.Document with{Assignments=[],Employees=[e],PlanningPeriod=new(new(2026,11,15),new(2026,11,15))};r=r with{Document=d,Start=new(2026,11,15),End=new(2026,11,15,23,59,59)};var candidates=new EscalaLivre.Infrastructure.Solver.ScheduleCandidateGenerator().Generate(r).ToArray();if(!inactive)Assert.True(candidates.Length>0,"candidate diagnostics: "+string.Join(",",ScheduleRules.ShiftDiagnostics(d.Company,EmploymentPolicy.On(e,r.Start),new(Guid.NewGuid(),e.Id,"Caixa",r.Start.AddHours(7.5),r.Start.AddHours(11.5),null,"solver",[],e.RoleHistory![0].RoleId),d.Roles).Select(c=>c.Code)));var result=AdapterComposition.Generate().Execute(r);Assert.Contains(result.Optimization!.Status,new[]{"optimal","feasible"});if(inactive)Assert.Empty(result.Assignments);else{Assert.NotEmpty(result.Assignments);Assert.All(result.Assignments,a=>{Assert.Equal("Caixa",a.Role);Assert.Equal(e.RoleHistory![0].RoleId,a.RoleId);});}var native=new NativeScheduleSerializer();var file=native.Export(new(d,"native"));var round=native.Import(new("escala.escalalivre",file.ContentBase64,"native"));Assert.Equal(e.RoleHistory![0].StartsOn,round.Employees[0].RoleHistory![0].StartsOn);Assert.Equal(e.InactiveFrom,round.Employees[0].InactiveFrom);}
}
